#!/usr/bin/env bash
# One CLI check and one Conda package manifest per image.
# Any program whose --help returns nonzero requires manual evaluation of output.
set -uo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"
mkdir -p manifests verification
echo "== Checking cutesv =="
docker run --rm --platform linux/amd64 --entrypoint conda sv-callers:cutesv-2.1.4 list --name sv --explicit > manifests/cutesv-linux-64-explicit.txt || echo "WARNING: package manifest failed for cutesv"
docker run --rm --platform linux/amd64 --entrypoint conda sv-callers:cutesv-2.1.4 list --name sv > manifests/cutesv-conda-list.txt || echo "WARNING: conda list failed for cutesv"
docker run --rm --platform linux/amd64 sv-callers:cutesv-2.1.4 --help > verification/cutesv-help.log 2>&1 || echo "NOTE: check exit code/help for cutesv; inspect verification/cutesv-help.log"
echo "== Checking debreak =="
docker run --rm --platform linux/amd64 --entrypoint conda sv-callers:debreak-1.3 list --name sv --explicit > manifests/debreak-linux-64-explicit.txt || echo "WARNING: package manifest failed for debreak"
docker run --rm --platform linux/amd64 --entrypoint conda sv-callers:debreak-1.3 list --name sv > manifests/debreak-conda-list.txt || echo "WARNING: conda list failed for debreak"
docker run --rm --platform linux/amd64 sv-callers:debreak-1.3 --help > verification/debreak-help.log 2>&1 || echo "NOTE: check exit code/help for debreak; inspect verification/debreak-help.log"
echo "== Checking delly =="
docker run --rm --platform linux/amd64 --entrypoint conda sv-callers:delly-2.7.0 list --name sv --explicit > manifests/delly-linux-64-explicit.txt || echo "WARNING: package manifest failed for delly"
docker run --rm --platform linux/amd64 --entrypoint conda sv-callers:delly-2.7.0 list --name sv > manifests/delly-conda-list.txt || echo "WARNING: conda list failed for delly"
docker run --rm --platform linux/amd64 sv-callers:delly-2.7.0 --help > verification/delly-help.log 2>&1 || echo "NOTE: check exit code/help for delly; inspect verification/delly-help.log"
echo "== Checking dysgu =="
docker run --rm --platform linux/amd64 --entrypoint conda sv-callers:dysgu-1.9.0 list --name sv --explicit > manifests/dysgu-linux-64-explicit.txt || echo "WARNING: package manifest failed for dysgu"
docker run --rm --platform linux/amd64 --entrypoint conda sv-callers:dysgu-1.9.0 list --name sv > manifests/dysgu-conda-list.txt || echo "WARNING: conda list failed for dysgu"
