docker run --rm --platform linux/amd64 sv-callers:nanomonsv-0.9.0 --help > verification/nanomonsv-help.log 2>&1 || echo "NOTE: check exit code/help for nanomonsv; inspect verification/nanomonsv-help.log"
echo "== Checking nanovar =="
docker run --rm --platform linux/amd64 --entrypoint conda sv-callers:nanovar-1.8.3 list --name sv --explicit > manifests/nanovar-linux-64-explicit.txt || echo "WARNING: package manifest failed for nanovar"
docker run --rm --platform linux/amd64 --entrypoint conda sv-callers:nanovar-1.8.3 list --name sv > manifests/nanovar-conda-list.txt || echo "WARNING: conda list failed for nanovar"
