echo "== Checking svim =="
docker run --rm --platform linux/amd64 --entrypoint conda sv-callers:svim-2.0.0 list --name sv --explicit > manifests/svim-linux-64-explicit.txt || echo "WARNING: package manifest failed for svim"
docker run --rm --platform linux/amd64 --entrypoint conda sv-callers:svim-2.0.0 list --name sv > manifests/svim-conda-list.txt || echo "WARNING: conda list failed for svim"
docker run --rm --platform linux/amd64 sv-callers:svim-2.0.0 --help > verification/svim-help.log 2>&1 || echo "NOTE: check exit code/help for svim; inspect verification/svim-help.log"
echo "Inspect the help logs and verify that installed versions match the manifests."
